var asm = Assembly.Load("ModelContextProtocol");
// Get ALL types including non-exported
foreach (var t in asm.GetTypes().Where(t => t.IsPublic || t.FullName.Contains("Tool") || t.FullName.Contains("Prompt") || t.FullName.Contains("Attribute")).OrderBy(t => t.FullName))
{
    if (t.FullName.Contains("Tool") || t.FullName.Contains("Prompt") || t.FullName.Contains("Attribute") || t.FullName.Contains("McpServer"))
    {
        Console.WriteLine($"\n=== {t.FullName} (public={t.IsPublic}) ===");
        if (t.BaseType != null && t.BaseType != typeof(object))
            Console.WriteLine($"  : {t.BaseType.Name}");
        foreach (var c in t.GetConstructors(BindingFlags.Public | BindingFlags.Instance))
            Console.WriteLine($"  ctor({string.Join(", ", c.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"))})");
        foreach (var p in t.GetProperties(BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly))
            Console.WriteLine($"  prop {p.PropertyType.Name} {p.Name}");
    }
}
