using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ApiTools
{
    /// <summary>Fetches a post by ID from the JSONPlaceholder API.</summary>
    [McpServerTool(Name = "get_post", ReadOnly = true), Description("Fetch a post by its numeric ID.")]
    public static async Task<string> GetPost(
        IHttpClientFactory httpClientFactory,
        [Description("The post ID (1-100).")] int id,
        CancellationToken cancellationToken)
    {
        using var client = httpClientFactory.CreateClient("ExternalApi");

        var response = await client.GetAsync($"posts/{id}", cancellationToken);
        response.EnsureSuccessStatusCode();

        var post = await response.Content.ReadFromJsonAsync<JsonElement>(cancellationToken);
        return post.ToString();
    }
}

using System.ComponentModel;
using ModelContextProtocol.Protocol;
using ModelContextProtocol.Server;

[McpServerPromptType]
public static class SummarizationPrompts
{
    [McpServerPrompt(Name = "summarize"), Description("Generate a concise summary of the provided text.")]
    public static GetPromptResult Summarize(
        [Description("The text to summarize.")] string text,
        [Description("Target length: 'short', 'medium', or 'long'.")] string length = "medium")
    {
        var instruction = length.ToLowerInvariant() switch
        {
            "short"  => "Summarize the following text in 1-2 sentences.",
            "long"   => "Provide a detailed summary of the following text, preserving key details.",
            _        => "Summarize the following text in a concise paragraph.",
        };

        return new()
        {
            Messages =
            [
                new()
                {
                    Role = Role.User,
                    Content = new TextContentBlock($"{instruction}\n\n{text}"),
                },
            ],
        };
    }
}

