1. using System.ComponentModel;
2. using ModelContextProtocol.Protocol;
3. using ModelContextProtocol.Server;
4. 
5. [McpServerPromptType]
6. public sealed class SummarizationPrompts
7. {
8.     [McpServerPrompt(Name = "summarize"), Description("Generate a concise summary of the provided text.")]
9.     public GetPromptResult Summarize(
10.         [Description("The text to summarize.")] string text,
11.         [Description("Target length: 'short', 'medium', or 'long'.")] string length = "medium")
12.     {
13.         var instruction = length.ToLowerInvariant() switch
14.         {
15.             "short"  => "Summarize the following text in 1-2 sentences.",
16.             "long"   => "Provide a detailed summary of the following text, preserving key details.",
17.             _        => "Summarize the following text in a concise paragraph.",
18.         };
19. 
20.         return new()
21.         {
22.             Messages =
23.             [
24.                 new()
25.                 {
26.                     Role = Role.User,
27.                     Content = new TextContentBlock { Text = $"{instruction}\n\n{text}" },
28.                 },
29.             ],
30.         };
31.     }
32. }
33.

